
insert into cda_orc_formulas_categoria(categoria_id,definicao)
select c.id,jsonb_build_object('forma','percentual','calculo','administracao','base','Receita Bruta (categoria 1) - Descontos sobre as Vendas (categoria 2)','percentual',case c.codigo when '6.1' then 10 else 2.5 end,'aplicacao','projeto')
from cda_orc_categorias c join cda_orc_tipos_projeto t on t.id=c.tipo_id where t.codigo=1 and c.codigo in('6.1','6.2')
on conflict(categoria_id) do update set definicao=excluded.definicao,atualizado_em=now();
update cda_orc_cadastros_projeto p set conteudo=(select jsonb_agg(case when c.id is not null then x||jsonb_build_object('formula',f.definicao)||case when not(x ? 'descritivo_calculo') and c.descritivo_calculo is not null then jsonb_build_object('descritivo_calculo',c.descritivo_calculo) else '{}'::jsonb end else x end order by ord) from jsonb_array_elements(p.conteudo) with ordinality z(x,ord) left join cda_orc_categorias c on c.id::text=x->>'id' and c.codigo in('6.1','6.2') left join cda_orc_formulas_categoria f on f.categoria_id=c.id) where p.chave='categorias';
update cda_orc_padroes_tipo p set conteudo=jsonb_set(p.conteudo,'{regras}',(select jsonb_agg(case when x->>'nome' in('Administração Direta','Administração Indireta') then x||jsonb_build_object('base','Venda após descontos comerciais e financeiros') else x end order by ord) from jsonb_array_elements(p.conteudo->'regras') with ordinality z(x,ord))),atualizado_em=now()
where p.chave='participacao' and p.tipo_id in(select id from cda_orc_tipos_projeto where codigo=1) and jsonb_typeof(p.conteudo->'regras')='array';
update cda_orc_cadastros_projeto p set conteudo=jsonb_set(p.conteudo,'{regras}',(select jsonb_agg(case when x->>'nome' in('Administração Direta','Administração Indireta') then x||jsonb_build_object('base','Venda após descontos comerciais e financeiros') else x end order by ord) from jsonb_array_elements(p.conteudo->'regras') with ordinality z(x,ord)))
where p.chave='participacao' and p.projeto_tipo_id in(select v.id from cda_orc_projeto_tipos v join cda_orc_tipos_projeto t on t.id=v.tipo_id where t.codigo=1) and jsonb_typeof(p.conteudo->'regras')='array';
